-- T-179 (ADR-83): 30 long-band catalogue exercises, one per cable exercise.
-- Generated by scripts/generate-band-long.py. Keys and our own enum values only: names, descriptions and
-- images live in the client bundle (ADR-38, ADR-39). Idempotent (on conflict do nothing).
-- muscle_group, metric_type and movement_pattern are copied from the cable source row.

insert into public.exercises (key, muscle_group, equipment, metric_type, movement_pattern, per_hand, is_custom, name)
select m.new_key, s.muscle_group, 'band_long', s.metric_type, s.movement_pattern, false, false, null
from (values
  ('band-long-cable-fly', 'cable-fly'),
  ('band-long-cable-crunch', 'cable-crunch'),
  ('band-long-cable-curl', 'cable-curl'),
  ('band-long-cable-hammer-curl', 'cable-hammer-curl'),
  ('band-long-cable-wrist-curl', 'cable-wrist-curl'),
  ('band-long-cable-front-raise', 'cable-front-raise'),
  ('band-long-cable-lateral-raise', 'cable-lateral-raise'),
  ('band-long-straight-bar-cable-front-raise', 'straight-bar-cable-front-raise'),
  ('band-long-single-arm-tricep-pushdown', 'single-arm-tricep-pushdown'),
  ('band-long-v-bar-tricep-pushdown', 'v-bar-tricep-pushdown'),
  ('band-long-cable-overhead-tricep-extension', 'cable-overhead-tricep-extension'),
  ('band-long-face-pull', 'face-pull'),
  ('band-long-lat-pulldown', 'lat-pulldown'),
  ('band-long-reverse-grip-lat-pulldown', 'reverse-grip-lat-pulldown'),
  ('band-long-close-grip-lat-pulldown', 'close-grip-lat-pulldown'),
  ('band-long-one-arm-lat-pulldown', 'one-arm-lat-pulldown'),
  ('band-long-straight-arm-pulldown', 'straight-arm-pulldown'),
  ('band-long-tricep-pushdown', 'tricep-pushdown'),
  ('band-long-cable-kickback', 'cable-kickback'),
  ('band-long-cable-tricep-kickback', 'cable-tricep-kickback'),
  ('band-long-cable-pallof-press', 'cable-pallof-press'),
  ('band-long-cable-chest-press', 'cable-chest-press'),
  ('band-long-cable-pull-through', 'cable-pull-through'),
  ('band-long-cable-bent-over-row', 'cable-bent-over-row'),
  ('band-long-seated-cable-row', 'seated-cable-row'),
  ('band-long-one-arm-seated-cable-row', 'one-arm-seated-cable-row'),
  ('band-long-cable-upright-row', 'cable-upright-row'),
  ('band-long-kneeling-cable-row', 'kneeling-cable-row'),
  ('band-long-wide-grip-seated-cable-row', 'wide-grip-seated-cable-row'),
  ('band-long-cable-external-rotation', 'cable-external-rotation')
) as m(new_key, source_key)
join public.exercises s on s.key = m.source_key and not s.is_custom
on conflict (key) where key is not null do nothing;

do $$
begin
  if (select count(*) from public.exercises where key like 'band-long-%' and equipment = 'band_long') <> 30 then
    raise exception 'band-long catalogue incomplete: a cable source row is missing';
  end if;
end $$;
